// UpdateNewValues updates the mutable fields using the new values that
// were set on create. Using this option is equivalent to using:
//
//	client.Shipment.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(shipment.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *ShipmentUpsertBulk) UpdateNewValues() *ShipmentUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(shipment.FieldID)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(shipment.FieldCreatedAt)
			}
			if _, exists := b.mutation.OrderGroupID(); exists {
				s.SetIgnore(shipment.FieldOrderGroupID)
			}
			if _, exists := b.mutation.StoreID(); exists {
				s.SetIgnore(shipment.FieldStoreID)
			}
			if _, exists := b.mutation.Provider(); exists {
				s.SetIgnore(shipment.FieldProvider)
			}
			if _, exists := b.mutation.QuoteID(); exists {
				s.SetIgnore(shipment.FieldQuoteID)
			}
			if _, exists := b.mutation.ServiceType(); exists {
				s.SetIgnore(shipment.FieldServiceType)
			}
			if _, exists := b.mutation.PickupAddress(); exists {
				s.SetIgnore(shipment.FieldPickupAddress)
			}
			if _, exists := b.mutation.DestinationAddress(); exists {
				s.SetIgnore(shipment.FieldDestinationAddress)
			}
		}
	}))
	return u
}

